class Solution {
    static int maxLucro(int[] precos) {
        if (precos.length == 0) return 0;
        int min = precos[0], best = 0;
        for (int p : precos) {
            best = Math.max(best, p - min);
            min = Math.min(min, p);
        }
        return best;
    }
}

