class Solution {
    static int[] produtoExceto(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        res[0] = 1;
        for (int i = 1; i < n; i++) res[i] = res[i - 1] * nums[i - 1];
        int dir = 1;
        for (int i = n - 1; i >= 0; i--) {
            res[i] *= dir;
            dir *= nums[i];
        }
        return res;
    }
}

