class Solution {
    static int[] twoSumII(int[] nums, int alvo) {
        int i = 0, j = nums.length - 1;
        while (i < j) {
            int s = nums[i] + nums[j];
            if (s == alvo) return new int[]{i, j};
            else if (s < alvo) i++;
            else j--;
        }
        return new int[]{-1, -1};
    }
}

