class Solution {
    static int maxArea(int[] altura) {
        int i = 0, j = altura.length - 1, best = 0;
        while (i < j) {
            int h = Math.min(altura[i], altura[j]);
            best = Math.max(best, h * (j - i));
            if (altura[i] < altura[j]) i++;
            else j--;
        }
        return best;
    }
}

