class Solution {
    static int maxSomaJanela(int[] nums, int k) {
        if (k > nums.length || k <= 0) return 0;
        int soma = 0;
        for (int i = 0; i < k; i++) soma += nums[i];
        int best = soma;
        for (int i = k; i < nums.length; i++) {
            soma += nums[i] - nums[i - k];
            best = Math.max(best, soma);
        }
        return best;
    }
}

