import java.util.*;

class Solution {
    static int[] intersecao(int[] a, int[] b) {
        Set<Integer> sa = new HashSet<>();
        for (int x : a) sa.add(x);
        TreeSet<Integer> comum = new TreeSet<>();
        for (int x : b) if (sa.contains(x)) comum.add(x);
        int[] r = new int[comum.size()];
        int i = 0;
        for (int x : comum) r[i++] = x;
        return r;
    }
}

