challenges.reference:
class Solution {
    static int[] sortColors(int[] nums) {
        int baixo = 0, meio = 0, alto = nums.length - 1;
        while (meio <= alto) {
            if (nums[meio] == 0) { troca(nums, baixo++, meio++); }
            else if (nums[meio] == 1) { meio++; }
            else { troca(nums, meio, alto--); }
        }
        return nums;
    }
    static void troca(int[] a, int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}

