import java.util.*;

class Solution {
    static int subarraySumK(int[] nums, int k) {
        Map<Integer, Integer> cont = new HashMap<>();
        cont.put(0, 1);
        int soma = 0, total = 0;
        for (int n : nums) {
            soma += n;
            total += cont.getOrDefault(soma - k, 0);
            cont.put(soma, cont.getOrDefault(soma, 0) + 1);
        }
        return total;
    }
}

